// 1. Получаем ID пользователя, который написал боту (из триггера)
const currentUserId = $('Telegram Trigger').item.json.message.from.id;

// 2. Собираем массив всех telegram_id из входящего JSON (из базы данных)
const dbIds = $input.all().map(item => item.json.telegram_id);

// 3. Проверяем, есть ли текущий ID в массиве базы данных
const exists = dbIds.includes(currentUserId);

// 4. Отдаем удобный результат для ноды IF
return [{
  json: {
    exists_in_db: exists,
    trigger_id: currentUserId,
    db_ids: dbIds
  }
}];

// 1. Ловим ID того, кто написал в бот
const chatId = $('Telegram Trigger').item.json.message.chat.id;

// 2. Получаем всех юзеров из предыдущей ноды Supabase
const allClients = $input.all();

// 3. Ищем в массиве строку, где telegram_id совпадает с chatId
const foundClient = allClients.find(client => Number(client.json.telegram_id) === Number(chatId));

if (!foundClient) {
  return [{
    json: {
      profile_text: "⚠️ Профиль не найден. Нажмите /start для регистрации."
    }
  }];
}

const user = foundClient.json;

// 4. Проверяем почту: если пустая (null), пишем предупреждение
let emailLine = "";
if (user.email) {
  emailLine = `📧 Email: ${user.email}`;
} else {
  emailLine = "📧 Email: Не указан ⚠️\n\nℹ️ Пожалуйста, заполните ваш Email на всякий случай.";
}

// 5. Собираем итоговое сообщение
const finalMessage = `👤 ЛИЧНЫЙ КАБИНЕТ\n\n` +
                   `📝 Имя: ${user.first_name || "Не указано"}\n` +
                   `💰 Баланс: ${user.balance || 0} Токенов.\n\n` +
                   `${emailLine}`;

// Передаем готовый текст в следующую ноду Телеграма
return [{
  json: {
    profile_text: finalMessage
  }
}];

// 1. Получаем ID текущего пользователя из Телеграма (берем из самого первого триггера)
const currentTelegramId = Number($('Telegram Trigger').item.json.message.chat.id);

// 2. Собираем ВСЕХ юзеров, которые пришли из Supabase
const allItems = $('GET Юзера').all();
const usersArray = allItems.map(item => item.json);

// 3. Ищем нашего пользователя в получившемся массиве
const currentUser = usersArray.find(user => {
  if (!user || !user.telegram_id) return false;
  return Number(user.telegram_id) === currentTelegramId;
});

// 4. Возвращаем результат
if (currentUser) {
  return { json: currentUser };
} else {
  return { 
    json: { 
      error: "Пользователь до сих пор не найден",
      debug_current_id: currentTelegramId,
      debug_total_users_found: usersArray.length,
      all_found_ids: usersArray.map(u => u.telegram_id) // выведем список всех ID, что смогли поймать
    } 
  };
}

// 1. Берем ID того, кто написал боту
const currentTelegramId = Number($('Telegram Trigger').item.json.message.chat.id);

// 2. Собираем всех юзеров из Supabase в один нормальный массив
const allUsers = $('GET Юзера').all().map(item => item.json);

// 3. Ищем конкретно твою строчку по ID
const currentUser = allUsers.find(user => Number(user.telegram_id) === currentTelegramId);

// Если тебя вообще нет в базе (странно, но на всякий случай)
if (!currentUser) {
  return {
    json: {
      user_found: false,
      go_to_branch: "create_new_key", // отправляем на создание
      reason: "Юзер вообще не найден в базе"
    }
  };
}

// 4. Проверяем твой личный vpn_key (смотрим, пустой он или нет)
const key = currentUser.vpn_key;
const isKeyEmpty = !key || key.toString().trim() === "" || key === null;

// 5. Выпускаем дальше все твои личные данные + готовый ответ, куда идти воркфлоу
return {
  json: {
    user_found: true,
    telegram_id: currentUser.telegram_id,
    balance: currentUser.balance,
    vpn_key: currentUser.vpn_key,
    first_name: currentUser.first_name,
    username: currentUser.username,
    // Вот эта переменная скажет, куда идти дальше
    go_to_branch: isKeyEmpty ? "create_new_key" : "show_existing_key"
  }
};
